using namespace Ui;
QWidget *MainWindow::makeFiles(){
 auto *page=new QWidget;auto *layout=new QVBoxLayout(page);layout->setContentsMargins(0,12,0,0);auto *box=card("标定文件版本 · 选中与生效分别记录");layout->addWidget(box,1);auto *bl=static_cast<QVBoxLayout *>(box->layout());auto *bar=new QHBoxLayout;
 fileKind_=new QComboBox;fileKind_->addItems({"手眼外参","相机内参","公共 TCP"});fileCamera_=new QComboBox;fileCamera_->addItems({"D455","Dabai"});bar->addWidget(fileKind_);bar->addWidget(fileCamera_);
 for(QString label:{"刷新列表","导入文件","查看原文","应用选中","重启受影响组件","恢复上一版本"}){auto *b=button(label,label=="应用选中");bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,label,b]{
  if(label=="刷新列表"){refreshFiles();return;}
  if(label=="导入文件"){
   auto path=QFileDialog::getOpenFileName(this,"导入标定候选",QString::fromLocal8Bit(qgetenv("AGX_ARM_WS")),"标定文件 (*.json *.yaml)");if(path.isEmpty())return;
   auto directory=QString::fromLocal8Bit(qgetenv("AGX_ARM_WS"))+"/data/calibration/"+(fileCamera_->currentIndex()==0?"d455":"dabai")+"/imported/";QDir().mkpath(directory);auto target=directory+QDateTime::currentDateTime().toString("yyyyMMdd-HHmmss-")+QFileInfo(path).fileName();if(!QFile::copy(path,target)){showError("标定文件导入失败");return;}refreshFiles();return;
  }
  if(label=="重启受影响组件"){request(b,"calibration.restart",{{"affected",affected_}},[this](QJsonValue v){toast_->setText("相关组件已重启 · 等待实际反馈；TCP 改变后请重新打开工作台加载模型");},"正在重启…","已重启");return;}
  if(label=="恢复上一版本"){if(lastBackup_.isEmpty()){showError("当前类型和相机没有可恢复的上一版本");return;}request(b,"calibration.restore",{{"backup",lastBackup_}},[this](QJsonValue v){affected_=v.toObject()["affected"].toArray();refreshFiles();toast_->setText("已恢复上一活动副本 · 等待重启");},"正在恢复…","已恢复");return;}
  auto row=files_->currentRow();if(row<0){showError("请先选中标定文件");return;}QString path=files_->item(row,0)->data(Qt::UserRole).toString();
  if(label=="查看原文"){QFile f(path);if(f.open(QFile::ReadOnly)){auto *dialog=new QDialog(this);dialog->setWindowTitle(path);dialog->resize(900,680);auto *l=new QVBoxLayout(dialog);auto *text=new QPlainTextEdit;text->setReadOnly(true);text->setPlainText(f.readAll());l->addWidget(text);dialog->setAttribute(Qt::WA_DeleteOnClose);dialog->show();}return;}
  request(b,"calibration.apply",{{"kind",fileKind_->currentIndex()==0?"handeye":fileKind_->currentIndex()==1?"intrinsics":"tcp"},{"camera_id",fileCamera_->currentIndex()==0?"d455":"dabai"},{"source_path",path}},[this](QJsonValue v){auto r=v.toObject();affected_=r["affected"].toArray();lastBackup_=r["backup"].toString();toast_->setText("活动副本已替换 · 等待重启受影响组件；原始质量记录保持原样");refreshFiles();},"正在应用…","已应用");
 });}
 bl->addLayout(bar);files_=new QTableWidget(0,5);files_->setHorizontalHeaderLabels({"文件 / 来源","类型","时间","质量 / 样本 / 误差","选中 / 生效"});files_->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);files_->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);files_->setSelectionBehavior(QAbstractItemView::SelectRows);files_->setEditTriggers(QAbstractItemView::NoEditTriggers);files_->verticalHeader()->hide();bl->addWidget(files_,1);bl->addWidget(text("应用表示你主动选用数值结果，质量指标保持原文。公共 TCP 需要重新启动机械臂 / MoveIt，并重新打开工作台以加载一致的模型。","notice"));
 connect(fileKind_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{refreshFiles();});connect(fileCamera_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{refreshFiles();});return page;
}
void MainWindow::refreshFiles(){backend_->call("calibration.list",{},[this](QJsonValue value){
 auto payload=value.toObject();calibrationFiles_=payload["files"].toArray();auto selections=payload["selections"].toObject();files_->setRowCount(0);QString kind=fileKind_->currentIndex()==0?"handeye":fileKind_->currentIndex()==1?"intrinsics":"tcp";QString camera=fileCamera_->currentIndex()==0?"d455":"dabai";
 auto selection=WorkbenchState::selection(selections,kind,camera);lastBackup_=selection["backup"].toString();affected_=selection["affected"].toArray();

 for(auto item:calibrationFiles_){auto row=item.toObject();auto data=row["data"].toObject();if(row["kind"].toString()!=kind)continue;QString path=row["path"].toString();if(kind!="tcp"&&row["camera_id"].toString()!=camera)continue;
  int i=files_->rowCount();files_->insertRow(i);auto *p=new QTableWidgetItem(QFileInfo(path).fileName());p->setData(Qt::UserRole,path);p->setToolTip(path);files_->setItem(i,0,p);files_->setItem(i,1,new QTableWidgetItem(kind=="tcp"?"公共 TCP":camera));files_->setItem(i,2,new QTableWidgetItem(QDateTime::fromMSecsSinceEpoch(qint64(row["modified"].toDouble()*1000)).toString("MM-dd HH:mm")));
  auto meta=data["metadata"].toObject();if(meta.isEmpty())meta=data["candidate"].toObject();QString quality=meta["quality_status"].toString(data["quality_status"].toString("未记录"));QString metrics=quality+" · "+QString::number(meta["frames_used"].toInt(data["frames"].toInt(data["sample_count"].toInt())));if(data.contains("rms_mm"))metrics+=" · RMS "+QString::number(data["rms_mm"].toDouble(),'f',3)+" mm";if(data.contains("reprojection_error"))metrics+=" · "+QString::number(data["reprojection_error"].toDouble(),'f',3)+" px";files_->setItem(i,3,new QTableWidgetItem(metrics));auto selected=selections[kind+":"+camera].toObject();if(kind=="tcp"&&selected.isEmpty())selected=selections["tcp:d455"].toObject();bool current=selected["source"].toString()==path||path.endsWith(selected["target"].toString())&&!selected.isEmpty();QString state=current?(selected["state"].toString()=="effective"?"已选用 · 实际数值一致":"已选用 · 等待重载 / 反馈"):path.contains("/config/calibration/")?"现有活动副本":"候选";auto *stateItem=new QTableWidgetItem(state);stateItem->setToolTip(current?selected["detail"].toString():path);files_->setItem(i,4,stateItem);
 }
 });}
QWidget *MainWindow::makeTeach(){
 auto *page=new QWidget;auto *row=new QHBoxLayout(page);row->setContentsMargins(0,12,0,0);auto *box=card("示教与放置方案");row->addWidget(box,3);auto *layout=static_cast<QVBoxLayout *>(box->layout());layout->addWidget(text("请通过机械臂上的实体按钮进入示教，摆到所需位置后读取。保存不会移动机械臂。","notice"));
 auto *bar=new QHBoxLayout;teachPlan_=new QComboBox;bar->addWidget(teachPlan_,1);planName_=new QLineEdit;planName_->setPlaceholderText("方案名称");bar->addWidget(planName_,1);auto *fresh=button("新建方案");bar->addWidget(fresh);layout->addLayout(bar);
 auto load=[this](int index){if(index<0)return;auto id=teachPlan_->itemData(index).toString();for(auto row:placements_["plans"].toArray())if(row.toObject()["id"]==id){teachDraft_=row.toObject();planName_->setText(teachDraft_["name"].toString());teachTable_->setRowCount(0);auto points=teachDraft_["via_joints_rad"].toArray();for(auto p:points){int i=teachTable_->rowCount();teachTable_->insertRow(i);teachTable_->setItem(i,0,new QTableWidgetItem(QString("途经点 %1").arg(i+1)));teachTable_->setItem(i,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(p.toArray()).toJson(QJsonDocument::Compact))));}if(teachDraft_.contains("release_joints_rad")){int i=teachTable_->rowCount();teachTable_->insertRow(i);teachTable_->setItem(i,0,new QTableWidgetItem("释放点"));teachTable_->setItem(i,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(teachDraft_["release_joints_rad"].toArray()).toJson(QJsonDocument::Compact))));}}};
 teachTable_=new QTableWidget(0,2);teachTable_->setHorizontalHeaderLabels({"位置顺序","实际关节角 (rad)"});teachTable_->horizontalHeader()->setSectionResizeMode(1,QHeaderView::Stretch);teachTable_->setEditTriggers(QAbstractItemView::NoEditTriggers);teachTable_->setSelectionBehavior(QAbstractItemView::SelectRows);layout->addWidget(teachTable_,1);
 connect(teachPlan_,qOverload<int>(&QComboBox::activated),this,load);connect(fresh,&QPushButton::clicked,this,[this]{teachDraft_={{"id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"name","新放置点"},{"via_joints_rad",QJsonArray{}}};planName_->setText("新放置点");teachTable_->setRowCount(0);});
 auto *controls=new QGridLayout;
 QStringList actions={"读取当前位置","添加途经点","替换所选点","上移","下移","移除","保存释放点","保存方案","删除方案","预览路线","执行示教路线"};auto *poseLabel=text("尚未读取实际反馈");layout->addWidget(poseLabel);
 for(int i=0;i<actions.size();++i){QString label=actions[i];auto *b=button(label,label=="保存方案");controls->addWidget(b,i/4,i%4);connect(b,&QPushButton::clicked,this,[this,label,poseLabel,load,b]{
  if(label=="读取当前位置"){request(b,"poses.capture",{},[this,poseLabel](QJsonValue v){lastActual_.clear();for(auto n:v.toObject()["joints_rad"].toArray())lastActual_<<n.toDouble();poseLabel->setText("实际反馈 · "+QString::fromUtf8(QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact)));},"正在读取…","已读取");return;}
  if(label=="保存方案"){
   if(!teachDraft_.contains("release_joints_rad")){showError("请读取并保存释放点");return;}teachDraft_["name"]=planName_->text();auto list=placements_["plans"].toArray();bool found=false;for(int j=0;j<list.size();++j)if(list[j].toObject()["id"]==teachDraft_["id"]){list[j]=teachDraft_;found=true;}if(!found)list.append(teachDraft_);placements_["plans"]=list;request(b,"placements.save",{{"data",placements_}},[this](QJsonValue v){placements_=v.toObject();refreshPlacements();toast_->setText("放置方案已保存 · 主页立即可选");},"正在保存…","已保存");return;
  }
  if(label=="删除方案"){
   auto id=teachDraft_["id"];auto sel=placements_["selection"].toObject();auto list=placements_["plans"].toArray();if(list.size()<2){showError("至少保留一个默认方案");return;}QJsonArray kept;for(auto p:list)if(p.toObject()["id"]!=id)kept.append(p);if(sel["default_plan_id"]==id)sel["default_plan_id"]=kept[0].toObject()["id"];auto maps=sel["class_to_plan_id"].toObject();QStringList changed;for(auto it=maps.begin();it!=maps.end();++it)if(it.value()==id){changed<<it.key();it.value()=sel["default_plan_id"];}sel["class_to_plan_id"]=maps;placements_["selection"]=sel;placements_["plans"]=kept;request(b,"placements.save",{{"data",placements_}},[this,changed](QJsonValue v){placements_=v.toObject();refreshPlacements();toast_->setText("方案已删除，受影响类别已回默认方案："+changed.join("、"));},"正在删除…","已删除");return;
  }
  if(label=="预览路线"||label=="执行示教路线"){
   if(!teachDraft_.contains("release_joints_rad")){showError("请先保存释放点");return;}
   // Full waypoint preview/execution uses the same manual MoveIt controller.
   QVector<QVector<double>> points;auto list=teachDraft_["via_joints_rad"].toArray();list.append(teachDraft_["release_joints_rad"]);for(auto p:list){QVector<double> v;for(auto x:p.toArray())v<<x.toDouble();points<<v;}motion_->route(points,velocity_->value()/100.,acceleration_->value()/100.,label=="执行示教路线");return;
  }
  auto points=teachDraft_["via_joints_rad"].toArray();int row=teachTable_->currentRow();
  if(label=="添加途经点"||label=="替换所选点"||label=="保存释放点"){
   // Read anew at the click: never save a cached control target as teaching feedback.
   request(b,"poses.capture",{},[this,label,row,load](QJsonValue value){auto joints=value.toObject()["joints_rad"].toArray();auto points=teachDraft_["via_joints_rad"].toArray();if(label=="保存释放点")teachDraft_["release_joints_rad"]=joints;else if(label=="添加途经点"){if(points.size()>=5){showError("途经点最多五个");return;}points.append(joints);}else if(row>=0&&row<points.size())points[row]=joints;else teachDraft_["release_joints_rad"]=joints;teachDraft_["via_joints_rad"]=points;
    teachTable_->setRowCount(0);for(int i=0;i<points.size();++i){teachTable_->insertRow(i);teachTable_->setItem(i,0,new QTableWidgetItem(QString("途经点 %1").arg(i+1)));teachTable_->setItem(i,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(points[i].toArray()).toJson(QJsonDocument::Compact))));}if(teachDraft_.contains("release_joints_rad")){int i=teachTable_->rowCount();teachTable_->insertRow(i);teachTable_->setItem(i,0,new QTableWidgetItem("释放点"));teachTable_->setItem(i,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(teachDraft_["release_joints_rad"].toArray()).toJson(QJsonDocument::Compact))));}
   });return;
  }
  if(row<0||row>=points.size())return;if(label=="移除")points.removeAt(row);else{int to=row+(label=="上移"?-1:1);if(to<0||to>=points.size())return;auto old=points[row];points[row]=points[to];points[to]=old;}teachDraft_["via_joints_rad"]=points;
  teachTable_->setRowCount(0);for(int j=0;j<points.size();++j){teachTable_->insertRow(j);teachTable_->setItem(j,0,new QTableWidgetItem(QString("途经点 %1").arg(j+1)));teachTable_->setItem(j,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(points[j].toArray()).toJson(QJsonDocument::Compact))));}if(teachDraft_.contains("release_joints_rad")){int i=teachTable_->rowCount();teachTable_->insertRow(i);teachTable_->setItem(i,0,new QTableWidgetItem("释放点"));teachTable_->setItem(i,1,new QTableWidgetItem(QString::fromUtf8(QJsonDocument(teachDraft_["release_joints_rad"].toArray()).toJson(QJsonDocument::Compact))));}
 });}layout->addLayout(controls);
 auto *side=card("参考位置与类别映射");row->addWidget(side,2);auto *sl=static_cast<QVBoxLayout *>(side->layout());
 for(auto pair:QList<QPair<QString,QString>>{{"保存当前为待机位","standby_joints_rad"},{"保存当前为 Dabai 观察位","dabai_observe_joints_rad"}}){auto *b=button(pair.first);sl->addWidget(b);connect(b,&QPushButton::clicked,this,[this,pair,b]{request(b,"poses.capture",{},[this,pair](QJsonValue v){auto refs=placements_["reference_poses"].toObject();refs[pair.second]=v.toObject()["joints_rad"];placements_["reference_poses"]=refs;backend_->call("placements.save",{{"data",placements_}},[this](QJsonValue){toast_->setText("参考位置已从实际反馈保存");});});});}
 sl->addWidget(text("按类别映射 JSON：键为模型原始类别名，值为稳定的方案 ID。改名不会破坏映射。"));auto *mapping=new QPlainTextEdit;mapping->setPlaceholderText("{\n  \"apple\": \"legacy-default\"\n}");sl->addWidget(mapping,1);auto *loadMap=button("读取当前映射");sl->addWidget(loadMap);connect(loadMap,&QPushButton::clicked,this,[this,mapping]{mapping->setPlainText(QJsonDocument(placements_["selection"].toObject()["class_to_plan_id"].toObject()).toJson(QJsonDocument::Indented));});auto *save=button("保存类别映射",true);sl->addWidget(save);connect(save,&QPushButton::clicked,this,[this,mapping,save]{QJsonParseError error;auto data=QJsonDocument::fromJson(mapping->toPlainText().toUtf8(),&error);if(error.error!=QJsonParseError::NoError||!data.isObject()){showError("类别映射 JSON 格式错误");return;}auto selection=placements_["selection"].toObject();selection["class_to_plan_id"]=data.object();placements_["selection"]=selection;request(save,"placements.save",{{"data",placements_}},[this](QJsonValue v){placements_=v.toObject();toast_->setText("类别映射已保存");},"正在保存…","已保存");});return page;
}
QWidget *MainWindow::makeAdvanced(){
 auto *page=new QWidget;auto *layout=new QVBoxLayout(page);layout->setContentsMargins(0,12,0,0);
 auto *row=new QHBoxLayout;layout->addLayout(row,1);auto *coordinates=card("原坐标管理 · 实际 TCP");row->addWidget(coordinates,1);auto *cl=static_cast<QVBoxLayout *>(coordinates->layout());
 auto poses=std::make_shared<QJsonObject>();auto *list=new QListWidget;cl->addWidget(list,1);auto *name=new QLineEdit;name->setPlaceholderText("坐标名称");cl->addWidget(name);auto *details=text("读取已有 saved_poses.json；旧法兰点缺少朝向时保留原记录，并提示重新示教");cl->addWidget(details);
 auto reload=[this,poses,list]{backend_->call("poses.list",{},[poses,list](QJsonValue v){*poses=v.toObject();list->clear();for(auto it=poses->begin();it!=poses->end();++it){auto *item=new QListWidgetItem(it.key(),list);item->setToolTip(QJsonDocument(it.value().toObject()).toJson(QJsonDocument::Indented));}});};
 connect(list,&QListWidget::itemClicked,this,[name,details,poses](QListWidgetItem *item){name->setText(item->text());auto p=poses->value(item->text()).toObject();details->setText(QString("X %1 mm · Y %2 mm · Z %3 mm\n参考点 %4").arg(p["x"].toDouble()*1000.,0,'f',2).arg(p["y"].toDouble()*1000.,0,'f',2).arg(p["z"].toDouble()*1000.,0,'f',2).arg(p["_reference_frame"].toString("legacy_link6")));});
 for(QString action:{"读取坐标列表","保存当前实际 TCP","删除选中坐标"}){auto *b=button(action,action=="保存当前实际 TCP",action=="读取坐标列表"?"refresh":"save");cl->addWidget(b);connect(b,&QPushButton::clicked,this,[this,action,name,reload,b]{if(action=="读取坐标列表"){reload();return;}if(name->text().trimmed().isEmpty()){showError("请输入坐标名称");return;}request(b,action=="保存当前实际 TCP"?"poses.save":"poses.delete",{{"name",name->text()}},[reload](QJsonValue){reload();},action=="保存当前实际 TCP"?"正在保存…":"正在删除…",action=="保存当前实际 TCP"?"已保存":"已删除");});}
 auto *queue=card("任务队列 · 原 sort 命令");row->addWidget(queue,2);auto *ql=static_cast<QVBoxLayout *>(queue->layout());auto *editor=new QPlainTextEdit;editor->setPlainText("[]");ql->addWidget(editor,1);auto *append=button("将所选坐标加入队列",false,"grab");ql->addWidget(append);connect(append,&QPushButton::clicked,this,[this,poses,list,editor]{if(!list->currentItem())return;QJsonParseError error;auto doc=QJsonDocument::fromJson(editor->toPlainText().toUtf8(),&error);if(error.error!=QJsonParseError::NoError||!doc.isArray()){showError("队列应为 JSON 数组");return;}auto tasks=doc.array();auto key=list->currentItem()->text();tasks.append(QJsonObject{{"cmd","sort"},{"camera_id",camera()},{"pick",poses->value(key)},{"pick_name",key},{"place_name","放置点"}});editor->setPlainText(QJsonDocument(tasks).toJson(QJsonDocument::Indented));});
 auto *controls=new QGridLayout;QStringList actions={"载入队列","保存队列","读取待派发队列","执行队列","当前物体后暂停","清空待派发"};for(int i=0;i<actions.size();++i){auto action=actions[i];auto *b=button(action,action=="执行队列",action=="执行队列"?"play":"logs");controls->addWidget(b,i/3,i%3);connect(b,&QPushButton::clicked,this,[this,action,editor,b]{
  if(action=="载入队列"){auto path=QFileDialog::getOpenFileName(this,"读取旧任务队列",QString::fromLocal8Bit(qgetenv("AGX_ARM_WS")),"JSON (*.json)");QFile file(path);if(file.open(QFile::ReadOnly))editor->setPlainText(file.readAll());return;}
  if(action=="保存队列"){auto path=QFileDialog::getSaveFileName(this,"保存任务队列",QString::fromLocal8Bit(qgetenv("AGX_ARM_WS"))+"/config/workbench/tasks.json");if(path.isEmpty())return;QSaveFile file(path);if(!file.open(QFile::WriteOnly)){showError("队列文件无法写入");return;}file.write(editor->toPlainText().toUtf8());if(!file.commit())showError("保存队列失败");return;}
  if(action=="读取待派发队列"){request(b,"queue.get",{},[editor](QJsonValue v){editor->setPlainText(QJsonDocument(v.toArray()).toJson(QJsonDocument::Indented));},"正在读取…","已读取");return;}
  if(action=="当前物体后暂停"){request(b,"motion.pause_after_cycle",{},[this](QJsonValue){refresh();},"正在请求…","已请求");return;}
  if(action=="清空待派发"){request(b,"queue.clear",{},[editor](QJsonValue){editor->setPlainText("[]");},"正在清空…","已清空");return;}
  QJsonParseError error;auto doc=QJsonDocument::fromJson(editor->toPlainText().toUtf8(),&error);if(error.error!=QJsonParseError::NoError||!doc.isArray()){showError("队列应为原 sort 命令组成的 JSON 数组");return;}request(b,"queue.set",{{"tasks",doc.array()}},[this](QJsonValue){backend_->call("queue.start");},"正在载入…","已载入");
 });}ql->addLayout(controls);ql->addWidget(text("队列等待当前物体完成后再派发下一条；关窗暂停，碰撞恢复清空旧队列。","notice"));
 auto *belt=card("传送带方向标定");auto *bl=static_cast<QVBoxLayout *>(belt->layout());auto *bar=new QHBoxLayout;bar->addWidget(text("沿用原轨迹拟合：让物体随传送带移动，开始记录后再次点击结束并计算。不会替你启动传送带。"),1);auto *calibrate=button("开始 / 结束方向标定",false,"calibrate");bar->addWidget(calibrate);connect(calibrate,&QPushButton::clicked,this,[this,calibrate]{request(calibrate,"tools.conveyor_calibration",{},[this](QJsonValue v){toast_->setText(v.toObject()["detail"].toString());},"处理中…","已完成");});bl->addLayout(bar);layout->addWidget(belt);return page;
}
